INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (1, 24, '内蒙古草原自驾游，策马奔腾的自由感觉', '整理了这次自驾游的详细攻略，包括路线规划、加油站位置、住宿推荐、必备物品清单等，希望对准备自驾出行的朋友有帮助。', 3, 1, 0, 7431, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (2, 38, '台北夜市美食攻略，一晚上吃遍台湾味', '美食探店是我旅行中最喜欢的环节，发现隐藏在街巷里的宝藏小店，品尝最地道的当地风味，这就是旅行的乐趣所在。', 6, 1, 0, 6450, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (3, 13, '重庆网红打卡点合集，洪崖洞李子坝全攻略', '整理了这次旅行的所有拍照点和拍摄技巧，从机位选择到后期调色，教你拍出刷爆朋友圈的旅行照片！', 8, 1, 0, 5472, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (4, 18, '成都美食地图，最地道的川菜和小吃推荐', '整理了这座城市的美食攻略，从老字号到网红店，从早餐到夜宵，每一家都是我亲自探访的真实推荐。', 6, 1, 0, 1959, 0, 0, 0);
