INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (6, 28, '云南亲子研学游，大自然就是最好的课堂', '带孩子旅行需要做更多的准备工作，从行李清单到应急方案，分享我的亲子游准备经验。', 10, 1, 0, 9225, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (7, 18, '大理洱海边民宿推荐，躺在床上就能看日出', '这次住的民宿真的太惊艳了！从设计风格到服务细节，每一处都让人感到温馨和舒适。强烈推荐给大家！', 7, 1, 0, 1266, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (8, 25, '珠海长隆海洋王国，最详细的游玩攻略', '旅行是最好的教育，让孩子在旅途中开阔眼界、增长见识。分享一些亲子游的目的地推荐和注意事项。', 10, 1, 0, 6279, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (9, 27, '泰国清迈曼谷自由行，小众寺庙和网红咖啡厅', '第一次出国旅行，心情既兴奋又紧张。但当飞机降落在异国土地上的那一刻，所有的担心都烟消云散了。世界那么大，真的要出去看看！', 2, 1, 0, 9190, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (10, 42, '仙本那潜水攻略，探索海底的奇妙世界', '整理了这次海岛游的攻略，包括岛屿选择、酒店推荐、水上项目、美食打卡等，希望对准备去海岛度假的朋友有帮助。', 5, 1, 0, 890, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (11, 42, '泸沽湖湖景民宿推荐，摩梭风情的独特体验', '这次住的民宿真的太惊艳了！从设计风格到服务细节，每一处都让人感到温馨和舒适。强烈推荐给大家！', 7, 1, 0, 8125, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (12, 13, '西藏自驾318国道，一生必走一次的朝圣之路', '这次的旅行让我对祖国的大好河山有了更深的认识，每一处风景都美得让人窒息。从繁华的都市到宁静的古镇，从巍峨的雪山到清澈的湖泊，中国的美景真的太多太多了。', 1, 1, 0, 3697, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (13, 25, '玉龙雪山一日游，雪山之下的蓝月谷', '户外徒步需要做好充分的准备，安全永远是第一位的。分享一些我的徒步经验和装备推荐。', 4, 1, 0, 4234, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (14, 12, '厦门鼓浪屿3日文艺之旅，小清新打卡指南', '精心整理了这份攻略，包含了行程安排、住宿推荐、美食打卡和避坑指南。希望能帮助到准备出行的小伙伴们，一起感受旅途的美好！', 1, 1, 0, 7963, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (15, 44, '搭便车旅行记录，一路上的温暖与感动', '旅行的意义不在于花多少钱，而在于路上的风景和遇到的人。背包客的旅行方式让我更加深入地体验当地生活。', 9, 1, 0, 5069, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (16, 40, '内蒙古草原自驾游，策马奔腾的自由感觉', '自驾游的魅力在于自由，想停就停想走就走。沿途的风景、偶遇的惊喜、意外的发现，都是跟团游无法体验到的。分享我的自驾心得和路线规划。', 3, 1, 0, 9664, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (17, 9, '新疆独库公路最美拍照点，每一帧都是壁纸', '这些网红打卡点真的太出片了！不需要专业设备，手机也能拍出大片效果。分享具体的拍摄时间、角度和构图技巧。', 8, 1, 0, 8675, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (18, 17, '普吉岛自由行，泰国海岛的热带风情', '选择海岛度假就是选择慢生活，不需要赶景点、不需要早起，只需要尽情享受阳光、沙滩和海浪。', 5, 1, 0, 8414, 0, 0, 0);
