INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (59, 28, '云南大理丽江7日深度游攻略，小众秘境全收录', '整理了一份超详细的攻略，从交通、住宿到每天的行程安排都有详细介绍，还有很多省钱小技巧分享给大家！', 1, 1, 0, 8430, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (60, 37, '背包客旅行装备清单，轻装上阵省钱省力', '谁说旅行一定要花很多钱？只要做好攻略、合理规划，用很少的预算也能有精彩的旅行体验。分享我的穷游经验和省钱技巧。', 9, 1, 0, 2460, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (61, 8, '青海湖茶卡盐湖环线游，天空之镜太美了', '旅行的意义不仅在于看风景，更在于路上遇到的人和事。这次旅途中认识了很多有趣的朋友，听到了很多动人的故事，这些都是旅行最珍贵的收获。', 1, 1, 0, 4071, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (62, 24, '冰岛极光拍摄攻略，追光者的终极指南', '整理了这次旅行的所有拍照点和拍摄技巧，从机位选择到后期调色，教你拍出刷爆朋友圈的旅行照片！', 8, 1, 0, 5164, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (63, 40, '哈巴雪山攀登记录，5396米的挑战与感动', '登山的过程虽然辛苦，但当你站在山顶俯瞰群山的那一刻，所有的疲惫都值得了。山就在那里，等待着每一个勇敢的攀登者。', 4, 1, 0, 8112, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (64, 49, '韩国首尔济州岛5日游，追星购物美食全攻略', '第一次出国旅行，心情既兴奋又紧张。但当飞机降落在异国土地上的那一刻，所有的担心都烟消云散了。世界那么大，真的要出去看看！', 2, 1, 0, 4830, 0, 0, 0);
