INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (151, 49, '成都重庆双城记，吃货的天堂之旅', '整理了一份超详细的攻略，从交通、住宿到每天的行程安排都有详细介绍，还有很多省钱小技巧分享给大家！', 1, 1, 0, 5252, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (152, 6, '三亚亲子游攻略，海边溜娃的完美行程', '带娃旅行虽然累但很值得，看到孩子开心的笑脸，所有的辛苦都变成了幸福。分享这次亲子游的经验和心得。', 10, 1, 0, 2727, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (153, 49, '潮汕美食之旅，牛肉火锅和各种粿品', '美食探店是我旅行中最喜欢的环节，发现隐藏在街巷里的宝藏小店，品尝最地道的当地风味，这就是旅行的乐趣所在。', 6, 1, 0, 2467, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (154, 49, '巴厘岛乌布度假，海岛与文化的完美结合', '选择海岛度假就是选择慢生活，不需要赶景点、不需要早起，只需要尽情享受阳光、沙滩和海浪。', 5, 1, 0, 5552, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (155, 44, '云南大理丽江7日深度游攻略，小众秘境全收录', '旅行的意义不仅在于看风景，更在于路上遇到的人和事。这次旅途中认识了很多有趣的朋友，听到了很多动人的故事，这些都是旅行最珍贵的收获。', 1, 1, 0, 150, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (156, 36, '苏梅岛5日慢生活，泰国最悠闲的海岛', '潜水让我发现了一个全新的世界，海底的珊瑚、热带鱼、海龟都美得不真实。如果你还没试过潜水，一定要去体验一次！', 5, 1, 0, 199, 0, 0, 0);
