INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (195, 24, '成都大熊猫基地亲子游，和国宝近距离接触', '带孩子旅行需要做更多的准备工作，从行李清单到应急方案，分享我的亲子游准备经验。', 10, 1, 0, 1483, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (196, 18, '三亚亚龙湾度假攻略，国内最美海滩推荐', '选择海岛度假就是选择慢生活，不需要赶景点、不需要早起，只需要尽情享受阳光、沙滩和海浪。', 5, 1, 0, 8757, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (197, 30, '新疆独库公路最美拍照点，每一帧都是壁纸', '整理了这次旅行的所有拍照点和拍摄技巧，从机位选择到后期调色，教你拍出刷爆朋友圈的旅行照片！', 8, 1, 0, 3406, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (198, 38, '珠海长隆海洋王国，最详细的游玩攻略', '带孩子旅行需要做更多的准备工作，从行李清单到应急方案，分享我的亲子游准备经验。', 10, 1, 0, 3693, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (199, 4, '海南环岛自驾游，椰风海韵的热带天堂', '自驾游需要做好充分的准备，车辆检查、路线规划、应急物品等都很重要。分享一些我的自驾经验和注意事项。', 3, 1, 0, 1228, 0, 0, 0);
INSERT INTO posts (id, user_id, title, content, category_id, type, is_draft, view_count, like_count, collect_count, comment_count) VALUES (200, 1, '北京亲子游景点推荐，寓教于乐的首都之旅', '旅行是最好的教育，让孩子在旅途中开阔眼界、增长见识。分享一些亲子游的目的地推荐和注意事项。', 10, 1, 0, 3078, 0, 0, 0);
